import pandas as pd
import numpy as np
import json, base64, io
from datetime import datetime

df = pd.read_csv('/app/benchmark/data.csv')
df['date'] = pd.to_datetime(df['date'])
df['year'] = df['date'].dt.year
df['month'] = df['date'].dt.month
df['dayofweek'] = df['date'].dt.dayofweek
df['bmi'] = df['weight_kg'] / (df['height_cm']/100)**2
df['age_group'] = pd.cut(df['age'], bins=[18,25,35,45,59], labels=['18-24','25-34','35-44','45-59'])

# ── helpers ─────────────────────────────────────────────────────────────────
def j(v): return json.dumps(v)

MONTH_NAMES = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
DOW_NAMES   = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']

# palette
C_BLUE    = '#2563eb'
C_TEAL    = '#0d9488'
C_PURPLE  = '#7c3aed'
C_ORANGE  = '#ea580c'
C_PINK    = '#db2777'
C_GREEN   = '#16a34a'
C_AMBER   = '#d97706'
C_GRAY    = '#6b7280'
PALETTE   = [C_BLUE, C_TEAL, C_PURPLE, C_ORANGE, C_PINK, C_GREEN, C_AMBER]

# ── pre-compute all series ───────────────────────────────────────────────────
# KPIs
kpi_steps       = round(df['steps'].mean())
kpi_calories    = round(df['calories_burned'].mean(), 1)
kpi_sleep       = round(df['sleep_hours'].mean(), 2)
kpi_workout_pct = round(df['workout_type'].notna().mean()*100, 1)
kpi_stress      = round(df['stress_level'].mean(), 2)
kpi_hr          = round(df['heart_rate_avg'].mean(), 1)
kpi_water       = round(df['water_intake_liters'].mean(), 2)

# gender stats
gender_stats = df.groupby('gender').agg(
    steps=('steps','mean'), calories=('calories_burned','mean'),
    sleep=('sleep_hours','mean'), stress=('stress_level','mean'),
    hr=('heart_rate_avg','mean'), count=('user_id','count')
).round(1)

def participation_by(col):
    result = {}
    for g, grp in df.groupby(col):
        result[g] = round(grp['workout_type'].notna().mean()*100, 1)
    return result

gender_part = participation_by('gender')

# age group
age_steps = df.groupby('age_group', observed=False)['steps'].mean().round(0)
age_counts = df.groupby('age_group', observed=False).size()

# workout type distribution
wt_counts = df['workout_type'].value_counts()
wt_steps  = df.dropna(subset=['workout_type']).groupby('workout_type')['steps'].mean().round(0)
wt_cal    = df.dropna(subset=['workout_type']).groupby('workout_type')['calories_burned'].mean().round(1)
wt_stress = df.dropna(subset=['workout_type']).groupby('workout_type')['stress_level'].mean().round(2)
wt_dur    = df[df['workout_duration_minutes']>0].groupby('workout_type')['workout_duration_minutes'].mean().round(1)

# yearly series
yearly = df.groupby('year').agg(
    steps=('steps','mean'), calories=('calories_burned','mean'),
    sleep=('sleep_hours','mean'), stress=('stress_level','mean'),
    hr=('heart_rate_avg','mean')
).round(2)
yearly_part = df.groupby('year').apply(lambda x: round(x['workout_type'].notna().mean()*100,1), include_groups=False)

# monthly series
monthly_steps = df.groupby('month')['steps'].mean().round(0)
monthly_sleep = df.groupby('month')['sleep_hours'].mean().round(2)
monthly_cal   = df.groupby('month')['calories_burned'].mean().round(1)
monthly_part  = df.groupby('month').apply(lambda x: round(x['workout_type'].notna().mean()*100,1), include_groups=False)

# day of week
dow_steps = df.groupby('dayofweek')['steps'].mean().round(0)

# mood
mood_stats = df.groupby('mood').agg(
    steps=('steps','mean'), sleep=('sleep_hours','mean'),
    stress=('stress_level','mean'), calories=('calories_burned','mean')
).round(2)

# heart rate / sleep / calories distributions (for histograms – use bucket counts)
def hist_data(series, bins=20):
    counts, edges = np.histogram(series.dropna(), bins=bins)
    centers = [(edges[i]+edges[i+1])/2 for i in range(len(counts))]
    return [round(c,1) for c in centers], counts.tolist()

hr_x,    hr_y    = hist_data(df['heart_rate_avg'], 20)
sleep_x, sleep_y = hist_data(df['sleep_hours'],    18)
steps_x, steps_y = hist_data(df['steps'],          20)

# stress distribution
stress_counts = df['stress_level'].value_counts().sort_index()

# water intake vs stress correlation
water_stress = df.groupby('stress_level')['water_intake_liters'].mean().round(3)

# ── build HTML ───────────────────────────────────────────────────────────────

years = yearly.index.tolist()
months_labels = [MONTH_NAMES[m-1] for m in range(1,13)]
wt_list  = wt_counts.index.tolist()
wt_colors = PALETTE[:len(wt_list)]
mood_list = mood_stats.index.tolist()

HTML = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Fitness Tracker Health &amp; Activity Analytics Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js"></script>
<style>
  :root{{
    --bg:#f8fafc; --surface:#ffffff; --border:#e2e8f0;
    --text:#0f172a; --text2:#475569; --text3:#94a3b8;
    --blue:#2563eb; --teal:#0d9488; --purple:#7c3aed;
    --orange:#ea580c; --green:#16a34a; --pink:#db2777;
    --amber:#d97706; --red:#dc2626;
    --radius:12px; --shadow:0 1px 3px rgba(0,0,0,.08),0 1px 2px rgba(0,0,0,.06);
    --shadow-md:0 4px 6px -1px rgba(0,0,0,.1),0 2px 4px -2px rgba(0,0,0,.1);
  }}
  *{{box-sizing:border-box;margin:0;padding:0}}
  body{{font-family:'Inter',system-ui,-apple-system,sans-serif;background:var(--bg);color:var(--text);line-height:1.6}}
  /* layout */
  .page-wrap{{max-width:1280px;margin:0 auto;padding:0 24px 80px}}
  /* header */
  .report-header{{background:linear-gradient(135deg,#1e3a8a 0%,#1d4ed8 50%,#0d9488 100%);
    color:#fff;padding:56px 48px 48px;border-radius:var(--radius);margin:32px 0 40px;
    box-shadow:var(--shadow-md)}}
  .report-header h1{{font-size:2rem;font-weight:700;letter-spacing:-.02em;margin-bottom:8px}}
  .report-header .subtitle{{font-size:1rem;opacity:.85;margin-bottom:24px}}
  .header-meta{{display:flex;gap:32px;flex-wrap:wrap;font-size:.85rem;opacity:.8}}
  .header-meta span::before{{content:'● ';opacity:.6}}
  /* section */
  .section{{margin-bottom:48px}}
  .section-title{{font-size:1.35rem;font-weight:700;color:var(--text);margin-bottom:4px;
    padding-bottom:10px;border-bottom:2px solid var(--blue);display:flex;align-items:center;gap:10px}}
  .section-number{{display:inline-flex;align-items:center;justify-content:center;
    width:28px;height:28px;background:var(--blue);color:#fff;border-radius:50%;
    font-size:.8rem;font-weight:700;flex-shrink:0}}
  .section-subtitle{{font-size:.9rem;color:var(--text2);margin-bottom:20px;margin-top:4px}}
  /* KPI grid */
  .kpi-grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:16px;margin-bottom:32px}}
  .kpi-card{{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);
    padding:20px;box-shadow:var(--shadow)}}
  .kpi-card .kpi-label{{font-size:.75rem;font-weight:600;color:var(--text3);text-transform:uppercase;
    letter-spacing:.05em;margin-bottom:6px}}
  .kpi-card .kpi-value{{font-size:1.75rem;font-weight:700;color:var(--text);line-height:1}}
  .kpi-card .kpi-unit{{font-size:.85rem;font-weight:500;color:var(--text2);margin-top:4px}}
  .kpi-card.accent-blue{{border-top:3px solid var(--blue)}}
  .kpi-card.accent-teal{{border-top:3px solid var(--teal)}}
  .kpi-card.accent-purple{{border-top:3px solid var(--purple)}}
  .kpi-card.accent-orange{{border-top:3px solid var(--orange)}}
  .kpi-card.accent-green{{border-top:3px solid var(--green)}}
  .kpi-card.accent-pink{{border-top:3px solid var(--pink)}}
  .kpi-card.accent-amber{{border-top:3px solid var(--amber)}}
  /* chart grid */
  .chart-grid{{display:grid;gap:20px}}
  .chart-grid.cols-2{{grid-template-columns:1fr 1fr}}
  .chart-grid.cols-3{{grid-template-columns:1fr 1fr 1fr}}
  .chart-grid.cols-1-2{{grid-template-columns:1fr 2fr}}
  @media(max-width:900px){{
    .chart-grid.cols-2,.chart-grid.cols-3,.chart-grid.cols-1-2{{grid-template-columns:1fr}}
  }}
  .chart-card{{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);
    padding:24px;box-shadow:var(--shadow)}}
  .chart-card .chart-title{{font-size:.95rem;font-weight:600;color:var(--text);margin-bottom:4px}}
  .chart-card .chart-desc{{font-size:.78rem;color:var(--text3);margin-bottom:16px}}
  .chart-wrap{{position:relative;height:260px}}
  .chart-wrap.tall{{height:320px}}
  .chart-wrap.short{{height:200px}}
  /* data table */
  .data-table{{width:100%;border-collapse:collapse;font-size:.85rem}}
  .data-table th{{background:#f1f5f9;color:var(--text2);font-weight:600;font-size:.75rem;
    text-transform:uppercase;letter-spacing:.05em;padding:10px 14px;text-align:left;
    border-bottom:1px solid var(--border)}}
  .data-table td{{padding:10px 14px;border-bottom:1px solid var(--border);color:var(--text)}}
  .data-table tr:last-child td{{border-bottom:none}}
  .data-table tr:hover td{{background:#f8fafc}}
  /* badge */
  .badge{{display:inline-flex;align-items:center;padding:2px 10px;border-radius:999px;
    font-size:.72rem;font-weight:600}}
  .badge-blue{{background:#dbeafe;color:#1e40af}}
  .badge-green{{background:#dcfce7;color:#15803d}}
  .badge-orange{{background:#ffedd5;color:#9a3412}}
  .badge-purple{{background:#ede9fe;color:#5b21b6}}
  .badge-teal{{background:#ccfbf1;color:#0f766e}}
  .badge-amber{{background:#fef3c7;color:#92400e}}
  /* insight boxes */
  .insight-grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px}}
  .insight-card{{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);
    padding:20px;box-shadow:var(--shadow);border-left:4px solid var(--blue)}}
  .insight-card.green{{border-left-color:var(--green)}}
  .insight-card.orange{{border-left-color:var(--orange)}}
  .insight-card.purple{{border-left-color:var(--purple)}}
  .insight-card.teal{{border-left-color:var(--teal)}}
  .insight-card .insight-title{{font-size:.85rem;font-weight:700;color:var(--text);margin-bottom:6px}}
  .insight-card .insight-body{{font-size:.82rem;color:var(--text2);line-height:1.55}}
  .insight-card .insight-stat{{font-size:1.1rem;font-weight:700;margin-bottom:4px}}
  .insight-card .insight-stat.blue{{color:var(--blue)}}
  .insight-card .insight-stat.green{{color:var(--green)}}
  .insight-card .insight-stat.orange{{color:var(--orange)}}
  .insight-card .insight-stat.purple{{color:var(--purple)}}
  .insight-card .insight-stat.teal{{color:var(--teal)}}
  /* rec cards */
  .rec-grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:16px}}
  .rec-card{{background:linear-gradient(135deg,#f0f9ff,#e0f2fe);border:1px solid #bae6fd;
    border-radius:var(--radius);padding:20px}}
  .rec-card.green{{background:linear-gradient(135deg,#f0fdf4,#dcfce7);border-color:#bbf7d0}}
  .rec-card.purple{{background:linear-gradient(135deg,#faf5ff,#ede9fe);border-color:#ddd6fe}}
