  .hl-orange{{font-weight:700;color:var(--orange)}}
</style>
</head>
<body>
<div class="page-wrap">

<!-- HEADER -->
<div class="report-header">
  <h1>Fitness Tracker User Health &amp; Activity Analytics</h1>
  <div class="subtitle">Comprehensive analysis of daily health metrics, activity patterns, and lifestyle indicators &mdash; 2015–2025</div>
  <div class="header-meta">
    <span>Cohort: 4,000 daily records · 2015-01-01 → 2025-12-13</span>
    <span>Audience: Health Analytics Team</span>
    <span>Generated: {datetime.now().strftime('%B %d, %Y')}</span>
    <span>Dataset: Synthetic (Kaggle · fitness-tracker-dataset)</span>
  </div>
</div>

<!-- TOC -->
<div class="toc">
  <h3>Table of Contents</h3>
  <ul class="toc-list">
    <li><a href="#s1">1. User Demographics &amp; Body Metrics</a></li>
    <li><a href="#s2">2. Physical Activity &amp; Workout Patterns</a></li>
    <li><a href="#s3">3. Heart Rate, Sleep &amp; Calorie Burn</a></li>
    <li><a href="#s4">4. Lifestyle &amp; Wellness Indicators</a></li>
    <li><a href="#s5">5. Temporal Trends &amp; Seasonal Patterns</a></li>
    <li><a href="#s6">6. Key Insights &amp; Recommendations</a></li>
  </ul>
</div>

<!-- ── GLOBAL KPI BAR ── -->
<div class="kpi-grid">
  <div class="kpi-card accent-blue">
    <div class="kpi-label">Avg Daily Steps</div>
    <div class="kpi-value">{kpi_steps:,}</div>
    <div class="kpi-unit">steps / day</div>
  </div>
  <div class="kpi-card accent-teal">
    <div class="kpi-label">Avg Calories Burned</div>
    <div class="kpi-value">{kpi_calories}</div>
    <div class="kpi-unit">kcal / day</div>
  </div>
  <div class="kpi-card accent-purple">
    <div class="kpi-label">Avg Sleep Duration</div>
    <div class="kpi-value">{kpi_sleep}</div>
    <div class="kpi-unit">hours / night</div>
  </div>
  <div class="kpi-card accent-green">
    <div class="kpi-label">Workout Participation</div>
    <div class="kpi-value">{kpi_workout_pct}%</div>
    <div class="kpi-unit">of daily records</div>
  </div>
  <div class="kpi-card accent-orange">
    <div class="kpi-label">Avg Stress Level</div>
    <div class="kpi-value">{kpi_stress}</div>
    <div class="kpi-unit">out of 10</div>
  </div>
  <div class="kpi-card accent-pink">
    <div class="kpi-label">Avg Heart Rate</div>
    <div class="kpi-value">{kpi_hr}</div>
    <div class="kpi-unit">bpm</div>
  </div>
  <div class="kpi-card accent-amber">
    <div class="kpi-label">Avg Water Intake</div>
    <div class="kpi-value">{kpi_water}</div>
    <div class="kpi-unit">liters / day</div>
  </div>
</div>

<!-- ─────────────────────────────────────── -->
<!-- SECTION 1: Demographics                -->
<!-- ─────────────────────────────────────── -->
<div class="section" id="s1">
  <div class="section-title"><span class="section-number">1</span>User Demographics &amp; Body Metrics Overview</div>
  <div class="section-subtitle">Distribution of users by age, gender, height, and weight — identifying key demographic segments in the cohort.</div>

  <div class="chart-grid cols-2" style="margin-bottom:20px">
    <div class="chart-card">
      <div class="chart-title">Gender Distribution</div>
      <div class="chart-desc">2,025 Male (50.6%) · 1,975 Female (49.4%) — near-equal split</div>
      <div class="chart-wrap short"><canvas id="genderPie"></canvas></div>
