import pandas as pd
import numpy as np
import json
from datetime import datetime

df = pd.read_csv('/app/benchmark/data.csv')
df['date'] = pd.to_datetime(df['date'])
df['year'] = df['date'].dt.year
df['month'] = df['date'].dt.month
df['dayofweek'] = df['date'].dt.dayofweek
df['bmi'] = df['weight_kg'] / (df['height_cm']/100)**2
df['age_group'] = pd.cut(df['age'], bins=[18,25,35,45,59], labels=['18-24','25-34','35-44','45-59'])

def j(v): return json.dumps(v)

MONTH_NAMES = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
DOW_NAMES   = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']

C_BLUE   = '#2563eb'
C_TEAL   = '#0d9488'
C_PURPLE = '#7c3aed'
C_ORANGE = '#ea580c'
C_PINK   = '#db2777'
C_GREEN  = '#16a34a'
C_AMBER  = '#d97706'
PALETTE  = [C_BLUE, C_TEAL, C_PURPLE, C_ORANGE, C_PINK, C_GREEN, C_AMBER]

# ── KPIs
kpi_steps       = round(float(df['steps'].mean()))
kpi_calories    = round(float(df['calories_burned'].mean()), 1)
kpi_sleep       = round(float(df['sleep_hours'].mean()), 2)
kpi_workout_pct = round(float(df['workout_type'].notna().mean()*100), 1)
kpi_stress      = round(float(df['stress_level'].mean()), 2)
kpi_hr          = round(float(df['heart_rate_avg'].mean()), 1)
kpi_water       = round(float(df['water_intake_liters'].mean()), 2)

# ── Gender
gender_stats = df.groupby('gender').agg(
    steps=('steps','mean'), calories=('calories_burned','mean'),
    sleep=('sleep_hours','mean'), stress=('stress_level','mean'),
    hr=('heart_rate_avg','mean'), count=('user_id','count')
).round(1)
gender_part = {g: round(float(grp['workout_type'].notna().mean()*100), 1)
               for g, grp in df.groupby('gender')}

# ── Age group
age_steps  = df.groupby('age_group', observed=False)['steps'].mean().round(0)
age_counts = df.groupby('age_group', observed=False).size()

# ── Workout type
wt_counts = df['workout_type'].value_counts()
wt_list   = wt_counts.index.tolist()
wt_steps  = df.dropna(subset=['workout_type']).groupby('workout_type')['steps'].mean().round(0)
wt_cal    = df.dropna(subset=['workout_type']).groupby('workout_type')['calories_burned'].mean().round(1)
wt_stress = df.dropna(subset=['workout_type']).groupby('workout_type')['stress_level'].mean().round(2)
wt_dur    = df[df['workout_duration_minutes']>0].groupby('workout_type')['workout_duration_minutes'].mean().round(1)

# ── Yearly
yearly = df.groupby('year').agg(
    steps=('steps','mean'), calories=('calories_burned','mean'),
    sleep=('sleep_hours','mean'), stress=('stress_level','mean'),
    hr=('heart_rate_avg','mean')
).round(2)
yearly_part = df.groupby('year').apply(
