years = yearly.index.tolist()

# ── Monthly
monthly_steps = df.groupby('month')['steps'].mean().round(0)
monthly_sleep = df.groupby('month')['sleep_hours'].mean().round(2)
monthly_cal   = df.groupby('month')['calories_burned'].mean().round(1)
